  <legend>Program-Specific Intake</legend>
  <p>This program uses a different intake flow. Continue to proceed through the program-specific pages.</p>
  <div class="nav-buttons">
    <button type="button" class="btn btn-secondary prev">Previous</button>
    <button type="button" class="btn btn-primary next">Next</button>
  </div>
</fieldset>


Program-aware step filtering helpers.
“In the <script> block, right after:
const form = document.querySelector('form');
replace the next variable declarations down to and including
let current = 0;
with:”

const form       = document.querySelector('form');
let   steps      = []; // active steps will be computed
const barFill    = document.querySelector('#progressBar span');
const alertBox   = document.getElementById('stepAlert');
let   current    = 0;

const programSel = document.getElementById('program_id');
const titleEl    = document.getElementById('formTitle');
const allSteps   = Array.from(document.querySelectorAll('fieldset.step'));

function matchProgram(fs, pname){
  const rule = (fs.getAttribute('data-program-match')||'').trim().toLowerCase();
  if (!rule) return true;                  // no rule => always visible (Step 1)
  if (rule.startsWith('!')) return !pname.includes(rule.slice(1));
  return pname.includes(rule);
}
function recomputeSteps(){
  const pname = (programSel?.options[programSel.selectedIndex]?.text || '').toLowerCase();
  steps = allSteps.filter(fs => matchProgram(fs, pname));
}
function toggleRequired(container, enabled){
  container.querySelectorAll('input,select,textarea').forEach(el=>{
    if (enabled) {
      if (el.dataset.req === '1') { el.setAttribute('required',''); delete el.dataset.req; }
    } else {
      if (el.hasAttribute('required')) { el.dataset.req = '1'; el.removeAttribute('required'); }
    }
  });
}
function updateFlow(){
  const pname = (programSel?.options[programSel.selectedIndex]?.text || '').toLowerCase();
  recomputeSteps();
  allSteps.forEach(fs=>{
    const on = steps.includes(fs);
    fs.style.display = on ? '' : 'none';
    toggleRequired(fs, on);
    fs.classList.remove('active');
  });
  current = 0;
  showStep(current);
  localStorage.setItem('intake_program_id', programSel?.value || '');
  if (titleEl && programSel) {
    const label = programSel.options[programSel.selectedIndex]?.text || '';
    titleEl.textContent = label ? `Intake Packet – ${label}` : 'Intake Packet';
  }
}


Replace the original step init block with program-aware init.
“Find the block:

const savedStep = +localStorage.getItem('intake_step') || 0;
if (savedStep && savedStep < steps.length) current = savedStep;
...
steps.forEach((fs, i) => fs.classList.toggle('active', i === current));
barFill.style.width = ((current + 1) / steps.length * 100) + '%';
localStorage.setItem('intake_step', current);


Replace the whole block with:”

const savedProgram = localStorage.getItem('intake_program_id');
if (savedProgram && programSel) programSel.value = savedProgram;
if (programSel) programSel.addEventListener('change', updateFlow);
updateFlow();

const savedStep = +localStorage.getItem('intake_step') || 0;
if (savedStep && savedStep < steps.length) { showStep(savedStep); }
barFill.style.width = ((current + 1) / steps.length * 100) + '%';
localStorage.setItem('intake_step', current);


Keep Next/Prev working with filtered steps.
“No code change needed in your Next/Prev handlers. They already use steps[current]. With the replacements above, steps is the active subset.”

Persist program on change.
“Ensure the line programSel.addEventListener('change', updateFlow); from step 8 exists only once.”

