<script>
document.addEventListener('DOMContentLoaded', () => {
  const form       = document.querySelector('form');
  let   steps      = []; // active steps will be computed
  const barFill    = document.querySelector('#progressBar span');
  const alertBox   = document.getElementById('stepAlert');
  let   current    = 0;

  const programSel = document.getElementById('program_id');
  const titleEl    = document.getElementById('formTitle');
  const allSteps   = Array.from(document.querySelectorAll('fieldset.step'));

  function matchProgram(fs, pname){
    const rule = (fs.getAttribute('data-program-match')||'').trim().toLowerCase();
    if (!rule) return true;                  // no rule => always visible (Step 1)
    if (rule.startsWith('!')) return !pname.includes(rule.slice(1));
    return pname.includes(rule);
  }
  function recomputeSteps(){
    const pname = (programSel?.options[programSel.selectedIndex]?.text || '').toLowerCase();
    steps = allSteps.filter(fs => matchProgram(fs, pname));
  }
  function toggleRequired(container, enabled){
    container.querySelectorAll('input,select,textarea').forEach(el=>{
      if (enabled) {
        if (el.dataset.req === '1') { el.setAttribute('required',''); delete el.dataset.req; }
      } else {
        if (el.hasAttribute('required')) { el.dataset.req = '1'; el.removeAttribute('required'); }
      }
    });
  }
  function updateFlow(){
    const pname = (programSel?.options[programSel.selectedIndex]?.text || '').toLowerCase();
    recomputeSteps();
    allSteps.forEach(fs=>{
      const on = steps.includes(fs);
      fs.style.display = on ? '' : 'none';
      toggleRequired(fs, on);
      fs.classList.remove('active');
    });
    current = 0;
    showStep(current);
    localStorage.setItem('intake_program_id', programSel?.value || '');
    if (titleEl && programSel) {
      const label = programSel.options[programSel.selectedIndex]?.text || '';
      titleEl.textContent = label ? `Intake Packet – ${label}` : 'Intake Packet';
    }
  }
  const savedProgram = localStorage.getItem('intake_program_id');
  if (savedProgram && programSel) programSel.value = savedProgram;
  if (programSel) programSel.addEventListener('change', updateFlow);
  updateFlow();

  const savedStep = +localStorage.getItem('intake_step') || 0;
  if (savedStep && savedStep < steps.length) { showStep(savedStep); }
  barFill.style.width = ((current + 1) / steps.length * 100) + '%';
  localStorage.setItem('intake_step', current);

  // LocalStorage restore + save
  document.querySelectorAll('input,select,textarea').forEach(el => {
    const key = 'intake_' + el.name;
    const saved = localStorage.getItem(key);
    if (saved !== null) {
      if (el.type === 'checkbox' || el.type === 'radio') {
        el.checked = saved === '1';
      } else {
        el.value = saved;
      }
    }
    const evt = (el.tagName === 'SELECT' || el.type === 'checkbox' || el.type === 'radio') ? 'change' : 'input';
    el.addEventListener(evt, () => {
      const val = (el.type === 'checkbox' || el.type === 'radio') ? (el.checked ? '1' : '0') : el.value;
      localStorage.setItem(key, val);
    });
  });

  function showStep(i) {
    steps[current].classList.remove('active');
    current = i;
    steps[current].classList.add('active');
    barFill.style.width = ((current + 1) / steps.length * 100) + '%';
    localStorage.setItem('intake_step', current);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }

  function clearHighlights() {
    alertBox.style.display = 'none';
    alertBox.textContent = '';
    steps[current].querySelectorAll('.invalid-field').forEach(el => el.classList.remove('invalid-field'));
  }

  form.addEventListener('click', e => {
    if (e.target.classList.contains('next')) {
      clearHighlights();
      const invalid = Array.from(steps[current].querySelectorAll(':invalid'));
      if (invalid.length) {
        invalid.forEach(el => el.classList.add('invalid-field'));
        const names = invalid.map(el => {
          const byFor = steps[current].querySelector(`label[for="${el.id}"]`);
          const near = el.closest('.col')?.querySelector('label');
          return ((byFor ?? near)?.textContent || el.name || 'field').trim();
        });
        alertBox.textContent = 'Please complete or correct: ' + names.join(', ');
        alertBox.style.display = 'block';
        alertBox.scrollIntoView({ behavior: 'smooth', block: 'start' });
        invalid[0].focus({ preventScroll: true });
        return;
      }
      if (current < steps.length - 1) showStep(current + 1);
    }

    if (e.target.classList.contains('prev')) {
      clearHighlights();
      if (current > 0) showStep(current - 1);
    }
  });

  form.addEventListener('input', e => {
    if (e.target.classList.contains('invalid-field') && e.target.checkValidity()) {
      e.target.classList.remove('invalid-field');
      if (!steps[current].querySelector(':invalid')) {
        alertBox.style.display = 'none';
      }
    }
  });

  // Page 4 – Household / Children logic
  const hasChildrenSel = document.getElementById('has_children');
  const childDetailsBox = document.getElementById('children-details');
  const neglectedSel = document.getElementById('children_neglected');
  const cpsBlock = document.getElementById('cps-block');
